const ECOFLOW_CONFIG = {
    "living_room": {
        "serial": "R600XXXXXXXX",
        "user_id": "1234567890123456789"
    }
};

global.set('ECOFLOW_CONFIG', ECOFLOW_CONFIG);
node.status({fill: 'green', shape: 'dot', text: Object.keys(ECOFLOW_CONFIG).length + ' device(s)'});
return msg;

const config = global.get('ECOFLOW_CONFIG') || {};
const serials = Object.values(config).map(d => d.serial);
const topicSerial = msg.topic.split('/').pop();

if (topicSerial && serials.includes(topicSerial) && msg.payload) {
    global.set('ecoflow_status_' + topicSerial, msg.payload);
    node.status({fill: 'green', shape: 'dot', text: 'updated ' + topicSerial});
}

return {
    topic: msg.topic,
    payload: msg.payload
};

const config = global.get('ECOFLOW_CONFIG') || {};
const name = msg.req.params.name;
const action1 = msg.req.params.action1;
const action2 = msg.req.params.action2;

const device = config[name];
if (!device) {
    msg.payload = {
        status: 'error',
        message: 'Device "' + name + '" not found in configuration. Available: ' + Object.keys(config).join(', ')
    };
    msg.statusCode = 404;
    return [null, msg];
}

const commands = {
    ac: {
        on: { id: 66, enabled: 1 },
        off: { id: 66, enabled: 0 }
    },
    dc: {
        on: { id: 34, enabled: 1 },
        off: { id: 34, enabled: 0 }
    },
    beep: {
        on: { id: 38, enabled: 1 },
        off: { id: 38, enabled: 0 }
    },
    xboost: {
        on: { id: 66, xboost: 1 },
        off: { id: 66, xboost: 0 }
    }
};

const cmdGroup = commands[action1];
if (!cmdGroup || !cmdGroup[action2]) {
    msg.payload = {
        status: 'error',
        message: 'Unknown action "' + action1 + '/' + action2 + '"'
    };
    msg.statusCode = 400;
    return [null, msg];
}

const params = cmdGroup[action2];
const cmdId = Date.now();

const topic = '/app/' + device.user_id + '/' + device.serial + '/thing/property/set';
const command = {
    from: 'Android',
    operateType: 'TCP',
    id: cmdId,
    lang: 'en-us',
    params: params,
    version: '1.0'
};

const mqttMsg = {
    topic: topic,
    payload: command
};

msg.payload = {
    status: 'ok',
    action: action1 + '_' + action2,
    device: name,
    message: 'Command sent to ' + name
};

return [mqttMsg, msg];

const config = global.get('ECOFLOW_CONFIG') || {};
const name = msg.req.params.name;
const device = config[name];

if (!device) {
    msg.payload = {
        status: 'error',
        message: 'Device "' + name + '" not found in configuration. Available: ' + Object.keys(config).join(', ')
    };
    msg.statusCode = 404;
    return msg;
}

const status = global.get('ecoflow_status_' + device.serial) || null;

msg.payload = {
    status: 'ok',
    action: 'status',
    device: name,
    state: status
};

return msg;

const manifest = {
    type: 'battery',
    brand: 'ecoflow',
    model: 'river',
    state_action: 'status',
    actions: [
        { id: 'ac_on', label: 'Encender AC', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/ac/on', icon: 'power' },
        { id: 'ac_off', label: 'Apagar AC', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/ac/off', icon: 'power-off' },
        { id: 'dc_on', label: 'Encender DC/CAR', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/dc/on', icon: 'car' },
        { id: 'dc_off', label: 'Apagar DC/CAR', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/dc/off', icon: 'car-off' },
        { id: 'beep_on', label: 'Beep ON', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/beep/on', icon: 'volume-2' },
        { id: 'beep_off', label: 'Beep OFF', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/beep/off', icon: 'volume-x' },
        { id: 'xboost_on', label: 'X-Boost ON', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/xboost/on', icon: 'zap' },
        { id: 'xboost_off', label: 'X-Boost OFF', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/xboost/off', icon: 'zap-off' },
        { id: 'status', label: 'Estado', method: 'GET', path: '/api/v1/home/battery/ecoflow/river/{name}/status', icon: 'activity', is_state: true }
    ]
};

msg.payload = manifest;
return msg;
